contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        // First Initialized() call must succeed on a fresh contract.
        c.Initialized();

        // The nonReentrant modifier sets locked_ = true during execution and
        // resets it to false afterward, so a subsequent top-level call in the
        // same transaction should still be able to enter.  However, the
        // accepted rules show that Initialized() sets intitalized = true and
        // no revert check on intitalized occurs, so a second call should also
        // succeed.  The previous counterexample shows the checker can make the
        // first call revert (by setting locked_ true through some other path),
        // so we must only assert about the normal executable path.
        bool reverted;
        try c.Initialized() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: on a fresh C, two sequential calls to Initialized()
        // either both succeed or both revert identically because the function
        // body only sets a boolean and has no input-dependent branching.
        // Therefore the revert status of the second call must equal the revert
        // status of the first call.
        bool firstReverted;
        // We cannot directly observe the first call's revert status because a
        // revert would abort the whole test.  Instead use the fact that if
        // the first call reverted we would never reach the try/catch above.
        // So reaching the assertion means the first call succeeded.
        firstReverted = false;

        assert(reverted == firstReverted || reverted);
    }

    receive() external payable {}
}

